// nnshim::ui: button prompts with PC keys and "menu" state for the mouse.
//
// 1) Button icons (A, B, ZR, sticks...). The game does not draw them with a font: they are BNTX
//    textures (BC4/BC5/BC3) in the layouts, inside the SARCs of bin/appli/**.arc (read via nn::fs) and
//    the GFLXPACKs of bin/archive/appli/*.gfpak (Oodle-compressed; the game decompresses them in
//    GFPack::LoadFile, main+0x2975d5c). A "key-prompt pack" (key_prompts.bin, generated by
//    tools/port/nnshim/key_prompts/gen_key_prompts.py from the user's controls) carries, per texture
//    (name + format + size), mip 0 already swizzled with the key drawn on it. The shim copies it
//    over the original:
//      - in nn::fs reads of an .arc (patches by file offset: it does not matter how the game
//        splits the reads), and
//      - in the output buffer of GFPack::LoadFile ("post" hook).
//    Keyboard mode only: ui.button_prompts = "auto" (keyboard if no controller is connected when the
//    layout loads), "keyboard" or "controller". A layout loaded after switching device already
//    comes out with the other mode's icons; resident ones (HUD) stay as they were loaded.
//
// 2) Menu state (for the mouse): game hooks that only run with a pause menu open or
//    with the field running (abi_ui.cpp); hid_core.cpp switches the mouse to menu mode meanwhile.
#pragma once

#include <cstddef>
#include <cstdint>
#include <cstring>
#include <map>
#include <string>
#include <utility>
#include <vector>

namespace nnshim::ui {

// ---- key-prompt pack --------------------------------------------------------------------------
struct PackEntry {
    std::string name;      // full texture name in the BNTX ("button_icon_A_00^t")
    uint32_t fmt = 0, w = 0, h = 0;
    std::vector<uint8_t> data;   // swizzled mip 0 (block-linear), exact size of the original
};

class Pack {
public:
    // Format: "PLATECL1", u32 n, n x { u16 len, name, u32 fmt, u32 w, u32 h, u32 size, data }.
    bool Load(const std::vector<uint8_t>& file, std::string* err = nullptr);
    bool Empty() const { return entries_.empty(); }
    size_t Size() const { return entries_.size(); }
    // nullptr if there is no replacement with that name, format, size and byte count.
    const PackEntry* Find(const std::string& name, uint32_t fmt, uint32_t w, uint32_t h, size_t size) const;

private:
    std::map<std::string, std::vector<PackEntry>> entries_;
};

// One texture of a BNTX (what is needed to replace it).
struct BntxTex {
    std::string name;
    uint32_t fmt = 0, w = 0, h = 0, mips = 0, bh_log2 = 0;
    uint64_t data_off = 0;   // mip 0, relative to the start of the BNTX
    uint64_t size = 0;       // mip 0 bytes (block-linear, computed)
};
// Reads the textures of a BNTX in buf[0..len). false if it is not a BNTX or is truncated.
bool ParseBntx(const uint8_t* buf, size_t len, std::vector<BntxTex>& out);
// Mip 0 bytes of a block-linear BCn texture (0 if the format is not BC1/BC3/BC4/BC5).
uint64_t SurfaceSize(uint32_t fmt, uint32_t w, uint32_t h, uint32_t bh_log2);

// BNTX textures that have a replacement in the pack (offset relative to the BNTX).
struct TexHit {
    uint64_t data_off;
    uint64_t size;
    const PackEntry* entry;
};
std::vector<TexHit> MatchBntx(const Pack& pack, const uint8_t* buf, size_t len);
// Replaces in memory the BNTX textures that are in the pack. Returns how many.
int PatchBntx(const Pack& pack, uint8_t* buf, size_t len);

// Icons already loaded in game memory, to swap them live (controller <-> keyboard). Stores,
// per texture, the guest address, the original bytes and the pack bytes. On a mode switch, it only
// rewrites a texture if its memory still holds exactly the other variant (if the game freed or
// reused that memory, the content no longer matches and the entry is dropped without writing).
class LiveSet {
public:
    // orig: original bytes (before patching); kb: keyboard variant (the pack's).
    void Add(uint64_t va, const uint8_t* orig, const uint8_t* kb, size_t size);
    // host(va, size) -> host pointer or nullptr. Returns how many textures were rewritten.
    template <class HostFn> int Swap(bool to_kb, HostFn host);
    size_t Size() const { return items_.size(); }
    static constexpr size_t kMax = 8192;

private:
    struct Item {
        uint64_t va;
        const uint8_t* kb;
        std::vector<uint8_t> orig;
    };
    std::vector<Item> items_;
};

template <class HostFn> int LiveSet::Swap(bool to_kb, HostFn host) {
    int n = 0;
    std::vector<Item> keep;
    keep.reserve(items_.size());
    for (Item& it : items_) {
        const size_t sz = it.orig.size();
        uint8_t* p = host(it.va, sz);
        if (!p) continue;
        const uint8_t* from = to_kb ? it.orig.data() : it.kb;
        const uint8_t* to = to_kb ? it.kb : it.orig.data();
        if (std::memcmp(p, to, sz) == 0) {
            keep.push_back(std::move(it));
        } else if (std::memcmp(p, from, sz) == 0) {
            std::memcpy(p, to, sz);
            ++n;
            keep.push_back(std::move(it));
        }   // other content: memory freed or reused -> forget it
    }
    items_ = std::move(keep);
    return n;
}

// Patch of a RomFS file: bytes [file_off, file_off + size) <- src.
struct FilePatch {
    uint64_t file_off;
    uint64_t size;
    const uint8_t* src;
};
// [start, end) of each BNTX file inside an in-memory SARC.
std::vector<std::pair<uint64_t, uint64_t>> SarcBntxRanges(const uint8_t* d, size_t len);
// Patches of a SARC (whole .arc file in `file`) against the pack.
std::vector<FilePatch> SarcPatches(const Pack& pack, const std::vector<uint8_t>& file);
// Applies to a read [off, off + n) in dst the patch pieces that overlap it. Returns bytes copied.
uint64_t ApplyPatches(const std::vector<FilePatch>& patches, uint64_t off, uint8_t* dst, uint64_t n);

// ---- icon mode --------------------------------------------------------------------------------
enum class PromptMode { Auto, Keyboard, Controller };
PromptMode PromptModeFromString(const std::string& s);   // unknown -> Auto
inline bool KeyboardPrompts(PromptMode m, bool pad_connected) {
    return m == PromptMode::Keyboard || (m == PromptMode::Auto && !pad_connected);
}

} // namespace nnshim::ui
